local function pureDecode(s)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #chars do map[chars:byte(i)] = i - 1 end
	local out, n = {}, 0
	for i = 1, #s, 4 do
		local a, b, c, d = s:byte(i, i + 3)
		local C, D = map[c], map[d]
		local v = (map[a] or 0) * 262144 + (map[b] or 0) * 4096 + (C or 0) * 64 + (D or 0)
		local b1, b2, b3 = math.floor(v / 65536), math.floor(v / 256) % 256, v % 256
		n += 1
		if C == nil then out[n] = string.char(b1)
		elseif D == nil then out[n] = string.char(b1, b2)
		else out[n] = string.char(b1, b2, b3) end
	end
	return table.concat(out)
end

local nativeDecode = (crypt and crypt.base64decode) or (crypt and crypt.base64 and (crypt.base64.decode or crypt.base64.Decode))
	or base64decode or base64_decode or (base64 and base64.decode)

local function decode(s)
	if nativeDecode then
		local ok, res = pcall(nativeDecode, s)
		if ok and type(res) == "string" and #res > 100 then return res end
	end
	return pureDecode(s)
end

local parent
pcall(function() parent = gethui and gethui() end)
if not parent then pcall(function() parent = game:GetService("CoreGui") end) end
if not parent then parent = lp:WaitForChild("PlayerGui") end
pcall(function()
	local old = parent:FindFirstChild("ZenithClanIntro")
	if old then old:Destroy() end
end)

local gui = Instance.new("ScreenGui")
gui.Name = "ZenithClanIntro"
gui.IgnoreGuiInset = true
gui.ResetOnSpawn = false
gui.DisplayOrder = 999999
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
gui.Parent = parent

local bg = Instance.new("Frame")
bg.Size = UDim2.fromScale(1, 1)
bg.BackgroundColor3 = Color3.new(0, 0, 0)
bg.BorderSizePixel = 0
bg.Parent = gui

local status = Instance.new("TextLabel")
status.AnchorPoint = Vector2.new(0.5, 0.5)
status.Position = UDim2.fromScale(0.5, 0.5)
status.Size = UDim2.fromScale(0.8, 0.06)
status.BackgroundTransparency = 1
status.Text = "Loading... 0%"
status.TextColor3 = Color3.fromRGB(200, 200, 200)
status.Font = Enum.Font.GothamBold
status.TextScaled = true
status.ZIndex = 10
status.Parent = bg

local endText = Instance.new("TextLabel")
endText.AnchorPoint = Vector2.new(0.5, 0.5)
endText.Position = UDim2.fromScale(0.5, 0.5)
endText.Size = UDim2.fromScale(0.6, 0.15)
endText.BackgroundTransparency = 1
endText.Text = "ZENITH CLAN🍁"
endText.TextScaled = true
endText.Font = Enum.Font.GothamBlack
endText.TextColor3 = Color3.new(1, 1, 1)
endText.TextTransparency = 1
endText.ZIndex = 20
endText.Parent = bg
local stroke = Instance.new("UIStroke")
stroke.Color = Color3.fromRGB(255, 120, 0)
stroke.Thickness = 3
stroke.Transparency = 1
stroke.Parent = endText

local written = {}
local function cleanup()
	if delfile then
		for _, name in ipairs(written) do pcall(delfile, name) end
	end
end

local function playEnd()
	local snd = Instance.new("Sound")
	snd.Volume = 3
	snd.Parent = gui
	local played = false
	if TOJI_VOICE_FILE ~= "" then
		pcall(function() snd.SoundId = getcustomasset(TOJI_VOICE_FILE); played = true end)
	end
	if not played and TOJI_VOICE_ID ~= "" then
		snd.SoundId = "rbxassetid://" .. TOJI_VOICE_ID
		played = true
	end
	if played then snd:Play() end

	TweenService:Create(endText, TweenInfo.new(0.5), {TextTransparency = 0}):Play()
	TweenService:Create(stroke, TweenInfo.new(0.5), {Transparency = 0}):Play()
	TweenService:Create(endText, TweenInfo.new(1.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Size = UDim2.fromScale(0.9, 0.25)}):Play()
	task.wait(4.5)
	TweenService:Create(endText, TweenInfo.new(0.8), {TextTransparency = 1}):Play()
	TweenService:Create(stroke, TweenInfo.new(0.8), {Transparency = 1}):Play()
	TweenService:Create(bg, TweenInfo.new(0.8), {BackgroundTransparency = 1}):Play()
	task.wait(0.9)
	gui:Destroy()
end

local function fail(msg)
	warn("[ZENITH] " .. tostring(msg))
	status.Text = tostring(msg)
	status.TextColor3 = Color3.fromRGB(255, 90, 90)
	task.wait(3)
	status.Visible = false
	cleanup()
	playEnd()
end

if not (writefile and getcustomasset) then
	return fail("Executor has no writefile/getcustomasset")
end

-- portrait holder (720x1280 shape)
local holder = Instance.new("Frame")
holder.AnchorPoint = Vector2.new(0.5, 0.5)
holder.Position = UDim2.fromScale(0.5, 0.5)
holder.Size = UDim2.fromScale(1, 1)
holder.BackgroundTransparency = 1
holder.Parent = bg
local ratio = Instance.new("UIAspectRatioConstraint")
ratio.AspectRatio = 720 / 1280
ratio.AspectType = Enum.AspectType.FitWithinMaxSize
ratio.DominantAxis = Enum.DominantAxis.Width
ratio.Parent = holder

-- decode + write frames
local labels = {}
local ok, err = pcall(function()
	for i = 1, NUM do
		local name = string.format("zc_frame_%03d.jpg", i)
		writefile(name, decode(F[i]))
		written[#written + 1] = name
		F[i] = nil
		local img = Instance.new("ImageLabel")
		img.Size = UDim2.fromScale(1, 1)
		img.BackgroundTransparency = 1
		img.BorderSizePixel = 0
		img.Image = getcustomasset(name)
		img.Visible = false
		img.Parent = holder
		labels[i] = img
		if i % 5 == 0 then
			status.Text = "Loading... " .. math.floor(i / NUM * 90) .. "%"
			task.wait()
		end
	end
	writefile("zc_audio.mp3", decode(AUDIO))
	written[#written + 1] = "zc_audio.mp3"
end)
F, AUDIO = nil, nil
if not ok then return fail("Load error: " .. tostring(err)) end

local sound = Instance.new("Sound")
sound.Volume = 1
sound.Parent = gui
pcall(function() sound.SoundId = getcustomasset("zc_audio.mp3") end)

-- preload images + audio
status.Text = "Loading... 95%"
pcall(function()
	local list = {}
	for _, l in ipairs(labels) do list[#list + 1] = l end
	list[#list + 1] = sound
	ContentProvider:PreloadAsync(list)
end)
local t0 = os.clock()
while not sound.IsLoaded and os.clock() - t0 < 4 do task.wait(0.1) end

status.Visible = false

-- play
local startT = os.clock()
sound:Play()
local last = 0
while true do
	local idx = math.floor((os.clock() - startT) * FPS) + 1
	if idx > NUM then break end
	if idx ~= last then
		if labels[last] then labels[last].Visible = false end
		labels[idx].Visible = true
		last = idx
	end
	RunService.RenderStepped:Wait()
end

pcall(function() sound:Stop() end)
holder.Visible = false
cleanup()
playEnd()
